window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[287]={"id":"287","numero":287,"titre":"Diverticulose colique - diverticulite aiguë","objectifs":[{"id":"287-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un diverticule, de la diverticulose, de la diverticulite, de la diverticulite compliquée (abcès, péritonite, fistule, hémorragie, sténose)","contenu":"<p>La <strong>maladie diverticulaire</strong> du côlon couvre un spectre allant de la simple présence de diverticules — totalement asymptomatique — jusqu'aux complications infectieuses et hémorragiques. Le vocabulaire est piégeux et tombe régulièrement à l'EDN.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Diverticule colique</span></td>\n            <td><strong>Hernie <span class=\"kw-etio\">acquise</span></strong> de la <span class=\"kw-def\">muqueuse</span> et de la <span class=\"kw-def\">sous-muqueuse</span> à travers une zone de faiblesse de la <strong>paroi musculaire</strong> du côlon, au point de pénétration des vaisseaux coliques.<br><strong>= pseudo-<span class=\"kw-clinique\">diverticule</span></strong> : il ne contient pas toute la paroi colique.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Diverticulose colique</span></td>\n            <td>Présence de diverticules <strong><span class=\"kw-etio\">acquis</span></strong> du côlon. État <strong>asymptomatique par définition</strong>, très fréquent.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Diverticulite</span></td>\n            <td><span class=\"kw-alerte\">Inflammation / infection</span> d'origine diverticulaire. La <strong>s<span class=\"kw-chiffre\">igm</span>oïdite diverticulaire</strong> (= <span class=\"kw-clinique\">diverticulite</span> sigmoïdienne) en est la forme habituelle.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Diverticulite compliquée</span></td>\n            <td>Complications locales de la <span class=\"kw-clinique\">diverticulite</span> : <span class=\"kw-alerte\">abcès</span> ; <span class=\"kw-alerte\">fistule</span> ; <span class=\"kw-alerte\">péritonite</span> d'origine diverticulaire ; <span class=\"kw-alerte\">sténose</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Maladie diverticulaire</span></td>\n            <td><span class=\"kw-clinique\">Diverticulite</span> (et ses complications) <strong>+</strong> <span class=\"kw-alerte\">hémorragie diverticulaire</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Localisation</span></td>\n            <td>En Occident, localisation prédominante = <strong>côlon s<span class=\"kw-chiffre\">igm</span>oïde</strong> et côlon gauche.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À distinguer.</strong> <span class=\"kw-clinique\">Les</span> diverticules coliques (<strong><span class=\"kw-etio\">acquis</span></strong>) sont à différencier des <strong>diverticules digestifs géants congénitaux</strong>, qui siègent sur le <span class=\"kw-def\">caecum</span>, le <span class=\"kw-def\">duodénum</span> et le <span class=\"kw-etio\">diverticule de Meckel</span>.\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/colonic-diverticulitis-1","label":"Radiopaedia : Colonic diverticulitis 1"},{"href":"https://radiopaedia.org/articles/hinchey-classification-of-acute-diverticulitis","label":"Radiopaedia : Hinchey classification of acute diverticulitis"},{"href":"https://radiopaedia.org/cases/colovesical-fistula-due-to-acute-sigmoid-diverticulitis","label":"Radiopaedia : Colovesical fistula due to acute sigmoid diverticulitis"},{"href":"https://radiopaedia.org/cases/active-diverticular-haemorrhage","label":"Radiopaedia : Active diverticular haemorrhage"}]},{"id":"287-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’incidence de la diverticulose et son histoire naturelle","contenu":"<p>La diverticulose est l'une des affections digestives <span class=\"kw-clinique\">les</span> plus fréquentes du sujet âgé en Occident. Sa fréquence augmente nettement avec l'<strong>âge</strong>.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span> de la diverticulose</strong></td>\n            <td><span class=\"kw-chiffre\">20-35 %</span> de la population générale.</td>\n          </tr>\n          <tr>\n            <td><strong>Diverticulose selon l'âge</strong></td>\n            <td><span class=\"kw-chiffre\">Très rare avant 30 ans</span> ; <span class=\"kw-chiffre\">50 %</span> à<span class=\"kw-chiffre\"> 50 ans</span> ; <span class=\"kw-chiffre\">65 %</span> après <span class=\"kw-chiffre\">65 ans</span> ; <span class=\"kw-chiffre\">60-80 %</span> après <span class=\"kw-chiffre\">85 ans</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Maladie diverticulaire</strong></td>\n            <td>Touche environ <span class=\"kw-chiffre\">5 %</span> de la population générale (hommes et femmes).</td>\n          </tr>\n          <tr>\n            <td><strong>Risque de <span class=\"kw-clinique\">diverticulite</span></strong></td>\n            <td>Parmi <span class=\"kw-clinique\">les</span> porteurs de diverticules, <span class=\"kw-chiffre\">10-35 %</span> feront une <span class=\"kw-clinique\">diverticulite</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Récidive après 1<sup>re</sup> <span class=\"kw-clinique\">poussée</span></strong></td>\n            <td>Risque de récidive à<span class=\"kw-chiffre\"> 5 ans</span> ≈ <span class=\"kw-chiffre\">30 %</span> — la majorité des récidives survient dans <span class=\"kw-clinique\">les</span> 5 premières années.</td>\n          </tr>\n          <tr>\n            <td><strong>Pic de fréquence de la <span class=\"kw-clinique\">diverticulite</span></strong></td>\n            <td>Le risque de <span class=\"kw-clinique\">diverticulite</span> augmente avec l'âge, <span class=\"kw-chiffre\">maximal entre 60 et 70 ans</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie diverticulaire — survenue</strong></td>\n            <td><span class=\"kw-chiffre\">5-10 %</span> des porteurs de diverticules feront une hémorragie diverticulaire au cours de leur vie.</td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie diverticulaire — <span class=\"kw-clinique\">évolution</span></strong></td>\n            <td>Résolution spontanée sous traitement conservateur dans <span class=\"kw-chiffre\">80-85 %</span> des cas ; récidive ≈ <span class=\"kw-chiffre\">15 %</span> après un 1<sup>er</sup> épisode, <span class=\"kw-chiffre\">50 %</span> après le 2<sup>e</sup>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <h5>Histoire naturelle</h5>\n      <ul>\n        <li>La diverticulose est <strong>asymptomatique</strong> : découverte <span class=\"kw-imagerie\">fortuite</span> en <span class=\"kw-imagerie\">coloscopie</span> ou en <span class=\"kw-imagerie\">TDM</span>.</li>\n        <li><strong>Aucune mesure préventive</strong> (régime, traitement, antiseptiques intestinaux) ne modifie l'histoire naturelle de la maladie.</li>\n        <li>Si une <span class=\"kw-alerte\">complication</span> doit survenir, elle survient le plus souvent dès la <strong>1<sup>re</sup> <span class=\"kw-clinique\">poussée</span></strong> — le risque de complication semble <strong>diminuer</strong> avec le nombre de poussées.</li>\n        <li><span class=\"kw-etio\">Âge jeune (&lt; 50 ans)</span> = <span class=\"kw-def\">facteur de risque</span> de <strong>récidive</strong> — d'où l'absence d'indication systématique de <span class=\"kw-ttt\">chirurgie</span> à froid à cet âge.</li>\n      </ul>","frequence":0},{"id":"287-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la maladie diverticulaire et de ses complications","contenu":"<p>La <span class=\"kw-def\">physiopathologie</span> de la maladie diverticulaire est <strong>multifactorielle</strong> et reste mal connue. Quatre grands déterminants sont à connaître.</p>\n      <table >\n        <thead><tr><th>Facteur</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Motricité colique</span></td>\n            <td>Implique <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">cellules pace-maker de Cajal</span> et certains neurotransmetteurs autonomes (<span class=\"kw-bio\">oxyde nitrique</span>, dont la répartition se modifie avec l'âge).<br><span class=\"kw-def\">Jonction recto-sigmoïdienne</span> : zone de <strong>haute pression intracolique</strong> qui favorise la genèse des diverticules en amont.<br>→ explique que les diverticules touchent <strong>surtout le s<span class=\"kw-chiffre\">igm</span>oïde (<span class=\"kw-chiffre\">90 %</span>)</strong> et <strong>jamais le rectum</strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Structure du collagène</span></td>\n            <td>Anomalie de la structure du collagène — explique le rôle de certaines <span class=\"kw-etio\">connectivites</span> dans <span class=\"kw-clinique\">les</span> formes compliquées.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Contenu colique</span></td>\n            <td>Anomalie du contenu colique : bol alimentaire <span class=\"kw-etio\">pauvre en fibres</span> ; rôle de la <span class=\"kw-etio\">flore colique</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">AINS</span></td>\n            <td><strong>Ne favorisent PAS la genèse</strong> des diverticules, mais bien la <span class=\"kw-alerte\">survenue de complications</span> :<br>↓ synthèse colique de prostaglandines → altération de la barrière muqueuse et <strong>hyperperméabilité colique</strong> ;<br>effet <span class=\"kw-etio\">toxique</span> direct → <span class=\"kw-alerte\">micro-perforations muqueuses</span> aboutissant à une péri-<span class=\"kw-clinique\">diverticulite</span> à germes digestifs.<br>Idem pour <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">immunosuppresseurs</span> et les <span class=\"kw-ttt\">antithrombotiques</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La <strong>complication <span class=\"kw-etio\">hémorragique</span></strong> relève d'un mécanisme distinct de la genèse des diverticules : <span class=\"kw-alerte\">érosion d'une artériole</span> au niveau du <strong>collet</strong> ou du <strong>fond</strong> du <span class=\"kw-clinique\">diverticule</span>.</p>\n      <div class=\"callout callout-info\">\n        <strong>Point chirurgical.</strong> La haute pression à la <strong>jonction recto-s<span class=\"kw-chiffre\">igm</span>oïdienne</strong> justifie que celle-ci soit <strong>toujours réséquée</strong> au cours de toute <span class=\"kw-ttt\">chirurgie</span> pour maladie diverticulaire.\n      </div>","frequence":0},{"id":"287-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un diverticule, d’une diverticulose, d’une diverticulite, d’une diverticulite compliquée","contenu":"<p>Le diagnostic repose sur l'<span class=\"kw-imagerie\">imagerie</span>. La présentation clinico-<span class=\"kw-ttt\">biologique</span> d'une <span class=\"kw-clinique\">diverticulite</span> est <strong>non spécifique</strong> : elle ne suffit jamais au diagnostic, y compris chez un patient déjà connu.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Modalités du diagnostic</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Diverticule / diverticulose</span></td>\n            <td>Découverte <strong>fortuite</strong> : <span class=\"kw-imagerie\">coloscopie</span> ou <span class=\"kw-imagerie\">TDM-TAP</span> — multiples <strong>images d'addition aérique</strong> du cadre colique.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Diverticulite</span></td>\n            <td><strong>Clinique non spécifique :</strong> <span class=\"kw-clinique\">douleur de la fosse iliaque gauche</span> ou de l'hypogastre ; <span class=\"kw-clinique\">fièvre modérée</span> ; <span class=\"kw-clinique\">troubles du transit</span> (<span class=\"kw-clinique\">constipation</span> surtout) ; signes fonctionnels urinaires.<br><strong>Diagnostic = <span class=\"kw-imagerie\">TDM-AP injectée</span> systématique en <span class=\"kw-alerte\">urgence</span></strong> : épaississement pariétal <span class=\"kw-chiffre\">&gt; 4 mm</span>, <span class=\"kw-ttt\">infiltration</span> de la graisse péricolique, signe du peigne (<span class=\"kw-clinique\">les</span> diverticules ne sont pas indispensables).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Diverticulite compliquée</span></td>\n            <td>La <span class=\"kw-imagerie\">TDM</span> recherche <span class=\"kw-clinique\">les</span> complications :<br><strong><span class=\"kw-clinique\">Abcès</span> :</strong> collection hypodense, paroi rehaussée, niveau hydro-aérique ;<br><strong><span class=\"kw-clinique\">Péritonite</span> :</strong> <span class=\"kw-imagerie\">pneumopéritoine</span>, épanchement liquidien ± granité fécal ;<br><strong><span class=\"kw-clinique\">Fistule</span> colo-vésicale :</strong> signe <span class=\"kw-imagerie\">TDM</span> = <span class=\"kw-alerte\">pneumovessie</span> ; cliniquement <span class=\"kw-clinique\">pneumaturie</span>, <span class=\"kw-clinique\">fécalurie</span> (pathognomonique), <span class=\"kw-clinique\">infections urinaires polymicrobiennes</span> à germes digestifs — <span class=\"kw-def\">terrain</span> : homme ou femme hystérectomisée ;<br><strong>Fistule colo-vaginale :</strong> beaucoup plus rare, ne survient que chez la <span class=\"kw-etio\">femme hystérectomisée</span> ; cliniquement <span class=\"kw-clinique\">émission de gaz / matières par voie vaginale</span> et <span class=\"kw-clinique\">infections vaginales récidivantes</span> ;<br><strong>Sténose :</strong> <span class=\"kw-def\">inflammatoire</span> (régresse sous <span class=\"kw-ttt\">antibiothérapie</span>) ou <span class=\"kw-alerte\">fibreuse pseudo-tumorale</span> (cicatricielle, après plusieurs poussées — ne régresse pas, relève de la <span class=\"kw-ttt\">chirurgie</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Contre-indiqués en contexte aigu.</strong> La <span class=\"kw-ci\">coloscopie conventionnelle</span>, la <span class=\"kw-ci\">coloscopie virtuelle</span> et le <span class=\"kw-ci\">lavement baryté</span> sont <strong><span class=\"kw-ci\">contre-indiqués</span></strong> à la phase aiguë (<span class=\"kw-alerte\">risque de perforation</span>). La <span class=\"kw-imagerie\">coloscopie</span> est réalisée à distance, après refroidissement.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — Douleur abdominale aiguë</em></p>","frequence":0},{"id":"287-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic différentiel d’une diverticule, d’une diverticulose, d’une diverticulite, d’une diverticulite compliquée","contenu":"<p>Trois confrontations différentielles tombent à l'EDN — la plus discriminante étant la <strong>sténose diverticulaire <span class=\"kw-bio\">vs</span> sténose cancéreuse</strong>.</p>\n      <h5><span class=\"kw-clinique\">Diverticulite</span> — autres causes de douleur de la fosse iliaque gauche</h5>\n      <ul>\n        <li><span class=\"kw-etio\">Colite</span> (infectieuse, <span class=\"kw-etio\">ischémique</span>, <span class=\"kw-etio\">inflammatoire</span>) ;</li>\n        <li><span class=\"kw-etio\">Appendicite</span> à présentation gauche (rare) ;</li>\n        <li><span class=\"kw-etio\">Pathologie gynécologique</span> (salpingite, torsion d'annexe, <span class=\"kw-ci\">grossesse</span> extra-utérine) ;</li>\n        <li><span class=\"kw-etio\">Colique néphrétique</span> gauche ;</li>\n        <li><span class=\"kw-alerte\">Cancer colorectal compliqué</span>.</li>\n      </ul>\n      <h5>Sténose diverticulaire <span class=\"kw-bio\">vs</span> sténose cancéreuse <em>(à distinguer — point majeur)</em></h5>\n      <table >\n        <thead><tr><th>Caractère <span class=\"kw-imagerie\">TDM</span></th><th>Sténose diverticulaire</th><th>Sténose cancéreuse</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Axe</strong></td>\n            <td><span class=\"kw-imagerie\">Centrée</span></td>\n            <td><span class=\"kw-alerte\">Excentrée</span></td>\n          </tr>\n          <tr>\n            <td><strong>Profil</strong></td>\n            <td><span class=\"kw-imagerie\">Progressive, à bords réguliers</span></td>\n            <td><span class=\"kw-alerte\">Bords irréguliers</span></td>\n          </tr>\n          <tr>\n            <td><strong>Raccordement au côlon sain</strong></td>\n            <td>Régulier</td>\n            <td><span class=\"kw-alerte\">À angle aigu</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes à distance</strong></td>\n            <td>Pas de <span class=\"kw-clinique\">lésion</span> évocatrice de métastase</td>\n            <td><span class=\"kw-clinique\">Adénopathies</span>, nodules hépatiques possibles</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Ne jamais méconnaître un cancer.</strong> Toute sténose impose une <span class=\"kw-imagerie\">coloscopie à distance</span> (après refroidissement de la <span class=\"kw-clinique\">poussée</span>) et, en cas de résection, l'<strong>analyse histologique systématique de la pièce opératoire</strong>.\n      </div>\n      <h5>Hémorragie diverticulaire — autres hémorragies digestives basses</h5>\n      <p>L'hémorragie diverticulaire est la <strong>première cause d'<span class=\"kw-clinique\">hémorragie digestive basse</span></strong> de sang rouge (≈ <span class=\"kw-chiffre\">1/3</span> des cas). À distinguer du <span class=\"kw-etio\">cancer colorectal</span>, de l'<span class=\"kw-etio\">angiodysplasie</span>, des <span class=\"kw-etio\">MICI</span> et de la <span class=\"kw-etio\">colite ischémique</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p>","frequence":0},{"id":"287-6","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les signes de gravité des deux urgences compliquant une maladie diverticulaire : une péritonite perforée et une hémorragie diverticulaire","contenu":"<p>Deux urgences peuvent compliquer une maladie diverticulaire : la <strong><span class=\"kw-clinique\">péritonite</span> perforée</strong> et l'<strong>hémorragie diverticulaire</strong>. Toutes deux imposent une évaluation immédiate de la gravité.</p>\n      <div class=\"callout callout-danger\">\n        <strong>1 — <span class=\"kw-clinique\">Péritonite</span> perforée (Hinchey 3-4).</strong>\n        <p><strong>2 types</strong> : <span class=\"kw-alerte\">stercorale</span> (perforation diverticulaire <strong>d'emblée en péritoine libre</strong>) <em><span class=\"kw-bio\">vs</span></em> <span class=\"kw-alerte\">purulente en 2 temps</span> (<strong><span class=\"kw-alerte\">rupture</span> secondaire</strong> d'un <span class=\"kw-clinique\">abcès</span> péri-s<span class=\"kw-chiffre\">igm</span>oïdien) — la charge <span class=\"kw-etio\">bactérienne</span> plus élevée explique que <span class=\"kw-clinique\">les</span> <strong>signes de <span class=\"kw-alerte\">choc</span> dominent dans la stercorale</strong>.</p>\n        <ul>\n          <li>Signes péritonéaux : <span class=\"kw-clinique\">contracture</span> (généralisée ou localisée à la FIG), <span class=\"kw-clinique\">défense</span>, <span class=\"kw-clinique\">douleur au toucher rectal</span> ;</li>\n          <li><span class=\"kw-clinique\">Syndrome occlusif</span> lié à un <span class=\"kw-clinique\">iléus</span> réflexe ;</li>\n          <li><span class=\"kw-alerte\">Syndrome infectieux</span> avec <span class=\"kw-clinique\">fièvre</span> élevée ;</li>\n          <li><span class=\"kw-alerte\">Signes de choc</span> — surtout dans la <span class=\"kw-clinique\">péritonite</span> stercorale (charge <span class=\"kw-etio\">bactérienne</span> élevée) ;</li>\n          <li>Drapeaux d'<span class=\"kw-clinique\">abcès</span> : <span class=\"kw-clinique\">défense en FIG</span> + <span class=\"kw-clinique\">douleur à la décompression abdominale brutale</span> ;</li>\n          <li>Biologie : <span class=\"kw-bio\">hyperPNN</span>, <span class=\"kw-bio\">CRP &gt; 5 mg/L</span>, <span class=\"kw-bio\">créatinine</span> (<span class=\"kw-ci\">insuffisance rénale</span> fonctionnelle si <span class=\"kw-alerte\">choc</span>) ;</li>\n          <li><span class=\"kw-imagerie\">TDM</span> : <span class=\"kw-imagerie\">pneumopéritoine</span>.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-danger\">\n        <strong>2 — Hémorragie diverticulaire.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Hémorragie digestive basse brutale</span> : <span class=\"kw-clinique\">rectorragie</span> / hématochézie abondante de <strong>sang rouge avec caillots</strong> ;</li>\n          <li>Plus rarement <span class=\"kw-clinique\">méléna</span> — si le <span class=\"kw-clinique\">diverticule</span> <span class=\"kw-etio\">hémorragique</span> siège <strong>en amont de l'angle colique gauche</strong> ;</li>\n          <li>Survient <strong>indépendamment</strong> d'une <span class=\"kw-clinique\">poussée</span> de <span class=\"kw-clinique\">diverticulite</span> — il n'y a <strong>pas de <span class=\"kw-clinique\">rectorragie</span></strong> dans la diverticulite simple ;</li>\n          <li>Retentissement hémodynamique <strong>variable</strong> : évaluer la tolérance — <span class=\"kw-clinique\">pression artérielle</span>, <span class=\"kw-clinique\">fréquence cardiaque</span>, recherche d'un <span class=\"kw-alerte\">choc hémorragique</span>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë · 355 — Hémorragie digestive · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"287-7","rang":"B","rubrique":"Etiologie","titre":"Connaître les facteurs de risque de complication","contenu":"<p>À distinguer des <span class=\"kw-def\">facteurs de risque</span> de la <strong>diverticulose</strong> elle-même (tabac, <span class=\"kw-etio\">obésité</span>, sédentarité, régime pauvre en fibres, <span class=\"kw-clinique\">constipation</span>, polykystose rénale) : voici <span class=\"kw-clinique\">les</span> facteurs de risque de <strong>complication</strong> et de <strong>récidive compliquée</strong>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs de risque</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-etio\">Insuffisance rénale chronique</span> ; <span class=\"kw-etio\">immunosuppression</span> (<span class=\"kw-ttt\">corticoïdes</span> ++) ; <span class=\"kw-etio\">rhumatismes inflammatoires</span> nécessitant des <span class=\"kw-ttt\">AINS</span> au long cours.</td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments</strong></td>\n            <td><span class=\"kw-ttt\">AINS</span> ; <span class=\"kw-ttt\">immunosuppresseurs</span> ; <span class=\"kw-ttt\">antithrombotiques</span> — ils favorisent <span class=\"kw-clinique\">les</span> <strong>complications</strong> (pas la genèse des diverticules).</td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie du 1<sup>er</sup> épisode</strong></td>\n            <td><span class=\"kw-alerte\">Signes de gravité</span> <span class=\"kw-imagerie\">TDM</span> : <span class=\"kw-alerte\">abcès</span> ; <span class=\"kw-imagerie\">fuite d'air</span> ; <span class=\"kw-imagerie\">fuite de produit de contraste extra-digestif</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie diverticulaire</strong></td>\n            <td>FR de survenue / récidive : <span class=\"kw-etio\">alcoolisme</span> ; <span class=\"kw-etio\">HTA</span> ; <span class=\"kw-ttt\">aspirine</span> ; <span class=\"kw-ttt\">AINS</span>.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"287-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie dans la maladie diverticulaire et ses complications","contenu":"<p>L'imagerie répond à deux questions distinctes : <strong>confirmer une <span class=\"kw-clinique\">diverticulite</span></strong> et <strong>localiser une hémorragie</strong>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Examen</th><th>Statut</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Suspicion de <span class=\"kw-clinique\">diverticulite</span></td>\n            <td><span class=\"kw-imagerie\">TDM-AP injectée</span></td>\n            <td><strong>Systématique en <span class=\"kw-alerte\">urgence</span></strong> — confirme le diagnostic et recherche <span class=\"kw-clinique\">les</span> complications. Opacification digestive basse aux hydrosolubles non systématique (peut accroître les performances).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Diverticulite</span> — examens inutiles</td>\n            <td><span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-imagerie\">échographie abdominale</span>, <span class=\"kw-imagerie\">IRM</span>, lavement aux hydrosolubles</td>\n            <td><strong>Non indiqués</strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Diverticulite</span> — phase aiguë</td>\n            <td><span class=\"kw-ci\">Lavement baryté</span>, <span class=\"kw-ci\">coloscopie conventionnelle</span>, <span class=\"kw-ci\">coloscopie virtuelle</span></td>\n            <td><strong>Contre-indiqués</strong> (risque de perforation). <span class=\"kw-imagerie\">Coloscopie</span> à distance ≈ <span class=\"kw-chiffre\">6 semaines</span> si forme compliquée ou <span class=\"kw-def\">dépistage</span> colique.</td>\n          </tr>\n          <tr>\n            <td>Hémorragie diverticulaire</td>\n            <td><span class=\"kw-imagerie\">EOGD</span> + <span class=\"kw-imagerie\">ano-rectosigmoïdoscopie</span>, puis <span class=\"kw-imagerie\">coloscopie totale</span></td>\n            <td><span class=\"kw-imagerie\">EOGD</span> pour éliminer une cause haute ; <span class=\"kw-imagerie\">coloscopie</span> totale dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 72 h</span> en l'absence de retentissement sévère (geste d'hémostase possible).</td>\n          </tr>\n          <tr>\n            <td>Hémorragie — 2<sup>e</sup> ligne</td>\n            <td><span class=\"kw-imagerie\">TDM-AP injectée</span>, <span class=\"kw-imagerie\">artériographie mésentérique</span></td>\n            <td>Indications rares : confirment l'origine diverticulaire et guident le traitement quand l'<span class=\"kw-imagerie\">endoscopie</span> ne localise pas le saignement.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"287-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie radiologique de la diverticulose et de ses complications","contenu":"<p>La <span class=\"kw-imagerie\">TDM-AP injectée</span> est l'examen pivot. Chaque entité a sa signature radiologique propre.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Sémiologie <span class=\"kw-imagerie\">TDM</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Diverticulose</span></td>\n            <td><span class=\"kw-imagerie\">Images d'addition aérique</span> du cadre colique.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Diverticulite</span></td>\n            <td><span class=\"kw-imagerie\">Diverticules</span> (présence non indispensable) ;<br><span class=\"kw-imagerie\">Épaississement pariétal</span> <span class=\"kw-chiffre\">&gt; 4 mm</span> ;<br><span class=\"kw-imagerie\">Infiltration de la graisse péricolique</span> ;<br><span class=\"kw-imagerie\">Signe du peigne</span> (hyperhémie du méso-s<span class=\"kw-chiffre\">igm</span>oïde) + épanchement liquidien à la racine du méso.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Abcès</span></td>\n            <td><span class=\"kw-imagerie\">Collection hypodense</span> ; <span class=\"kw-imagerie\">paroi qui se rehausse</span> ; contenu liquidien avec <span class=\"kw-imagerie\">niveau hydro-aérique</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Péritonite / perforation</span></td>\n            <td><span class=\"kw-imagerie\">Pneumopéritoine</span> : bulles d'<span class=\"kw-def\">air</span> péri-coliques + dans l'espace inter-hépato-diaphragmatique (souvent volumineux et bilatéral) ;<br><span class=\"kw-imagerie\">Épanchement liquidien péritonéal</span> ± granité fécal ;<br><span class=\"kw-imagerie\">Fort rehaussement péritonéal</span> après injection de produit de contraste.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Fistule sigmoïdo-vésicale</span></td>\n            <td><span class=\"kw-imagerie\">Pneumovessie</span> (<span class=\"kw-def\">air</span> dans la vessie) ± fuite de produit de contraste dans la vessie.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Hémorragie diverticulaire active</span></td>\n            <td><span class=\"kw-imagerie\">Extravasation de produit de contraste</span> dans la lumière colique (<span class=\"kw-imagerie\">TDM</span> injectée).</td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/287/tdm-diverticulose-diverticulite.png\" alt=\"TDM abdomino-pelvienne, coupes axiales avec injection au temps portal, de 4 patients distincts montrant un diverticule en image d'addition, une diverticulite sigmoïdienne avec épaississement pariétal et infiltration de la graisse, et une diverticulite compliquée avec abcès et perforation\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span>, coupes axiales avec injection au temps portal (4 patients distincts). <strong><span class=\"kw-clinique\">Diverticule</span> :</strong> <span class=\"kw-radio\">image d'addition</span> de contenu variable (aérique, matières, coprolithe). <strong><span class=\"kw-clinique\">Diverticulite</span> s<span class=\"kw-chiffre\">igm</span>oïdienne :</strong> <span class=\"kw-radio\">infiltration de la graisse centrée sur un diverticule</span> + <span class=\"kw-radio\">épaississement de la paroi sigmoïdienne</span>. <strong>Diverticulite compliquée :</strong> <span class=\"kw-alerte\">abcès</span> (collection hydro-aérique à parois épaisses) et <span class=\"kw-alerte\">perforation</span> (pneumopéritoine, matières intrapéritonéales). Source : banque imagerie « Imagerie à connaître » (item 287).</figcaption>\n      </figure>\n      <h5><span class=\"kw-def\">Classification</span> de Hinchey <em>(sévérité des infections intra-péritonéales)</em></h5>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th><span class=\"kw-clinique\">Lésion</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>1a</strong></td><td><span class=\"kw-alerte\">Phlegmon</span> péricolique isolé (<span class=\"kw-clinique\">phlegmon</span> = infection sans collection).</td></tr>\n          <tr><td><strong>1b</strong></td><td><span class=\"kw-alerte\">Abcès</span> péricolique isolé.</td></tr>\n          <tr><td><strong>2</strong></td><td><span class=\"kw-alerte\">Abcès</span> pelvien, abdominal ou rétropéritonéal = <strong><span class=\"kw-clinique\">péritonite</span> localisée</strong>.</td></tr>\n          <tr><td><strong>3</strong></td><td><span class=\"kw-alerte\">Péritonite généralisée purulente</span>.</td></tr>\n          <tr><td><strong>4</strong></td><td><span class=\"kw-alerte\">Péritonite stercorale / fécale</span>.</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"287-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge médicale d’une diverticulite aiguë non compliquée","contenu":"<p>La <span class=\"kw-clinique\">diverticulite</span> aiguë s<span class=\"kw-chiffre\">igm</span>oïdienne <strong>non compliquée</strong> se traite le plus souvent en <strong>ambulatoire</strong>. Tournant récent : l'<span class=\"kw-ttt\">antibiothérapie</span> n'est <strong>plus systématique</strong>.</p>\n      <h5>Mesures générales</h5>\n      <ul>\n        <li><span class=\"kw-ttt\">Antalgiques</span> ;</li>\n        <li>Régime alimentaire : <strong>phase aiguë</strong> → <span class=\"kw-ttt\">régime sans résidu</span> ; <strong>au long cours</strong> → <span class=\"kw-ttt\">alimentation non restrictive</span> recommandée (pas de fibres en moins, pas de régime d'éviction).</li>\n        <li>Bilan <span class=\"kw-ttt\">biologique</span> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP &gt; 5 mg/L</span> (<span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span>), <span class=\"kw-bio\">créatinine</span>.</li>\n      </ul>\n      <h5><span class=\"kw-ttt\">Antibiothérapie</span> per os</h5>\n      <table >\n        <thead><tr><th>Élément</th><th>Modalité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td><strong>Non systématique</strong> — réservée à la <span class=\"kw-alerte\">non-réponse au traitement symptomatique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Molécule</strong></td>\n            <td><span class=\"kw-ttt\">Amoxicilline - acide clavulanique</span> ;<br>si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">fluoroquinolone + métronidazole</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td><span class=\"kw-chiffre\">≤ 7 jours</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <h5>Indications d'<span class=\"kw-alerte\">hospitalisation</span></h5>\n      <ul>\n        <li>Forme <span class=\"kw-alerte\">compliquée</span> ;</li>\n        <li><span class=\"kw-ci\">Intolérance</span> alimentaire nécessitant une ATB par voie IV ;</li>\n        <li>Contexte social défavorable (<span class=\"kw-def\">surveillance</span> ambulatoire impossible) ;</li>\n        <li><span class=\"kw-def\">Comorbidité</span> significative ;</li>\n        <li>Absence d'amélioration après <span class=\"kw-chiffre\">48-72 h</span> de traitement ambulatoire.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À distance.</strong> Après un 1<sup>er</sup> épisode non compliqué : <span class=\"kw-imagerie\">surveillance clinique simple</span>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">corticoïdes</span> et <span class=\"kw-ttt\">AINS</span> sont déconseillés en cas d'ATCD de <span class=\"kw-clinique\">diverticulite</span>. La <span class=\"kw-ttt\">chirurgie</span> n'est <strong>pas systématique</strong> : le nombre de poussées n'est pas en soi une indication opératoire.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":1},{"id":"287-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge médicale initiale d’une diverticulite aiguë compliquée","contenu":"<p>Une <span class=\"kw-clinique\">diverticulite</span> aiguë <strong>compliquée</strong> impose une <strong><span class=\"kw-alerte\">hospitalisation</span> systématique</strong> et une <span class=\"kw-ttt\">antibiothérapie</span> par voie <strong>IV</strong>.</p>\n      <h5>Indications de l'<span class=\"kw-ttt\">antibiothérapie</span> IV</h5>\n      <table >\n        <thead><tr><th>Indication</th><th>Critères précis</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Grossesse</span></td>\n            <td>Quel que soit le terme — <span class=\"kw-alerte\">hospitalisation</span> systématique.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Complication ou signes de sepsis</span></td>\n            <td><span class=\"kw-chiffre\">qSOFA</span> <span class=\"kw-chiffre\">≥ 2</span> : PAS <span class=\"kw-chiffre\">≤ 100 mmHg</span>, FR <span class=\"kw-chiffre\">≥ 22/min</span>, confusion.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Comorbidité</span> significative</strong></td>\n            <td>Cancer évolutif, <span class=\"kw-etio\">insuffisance rénale terminale</span>, <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">ASA &gt; 3</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Immunodépression</span></td>\n            <td><span class=\"kw-etio\">Congénitale</span>, acquise, <span class=\"kw-ttt\">immunosuppresseurs</span> / immunomodulateurs, <span class=\"kw-ttt\">corticothérapie</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Voie</th><th>Schémas antibiotiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>IV</strong></td>\n            <td><span class=\"kw-ttt\">Amoxicilline - acide clavulanique + gentamicine</span> ;<br>OU <span class=\"kw-ttt\">C3G + métronidazole</span> ;<br>si <span class=\"kw-ci\">allergie</span> prouvée aux β-lactamines : <span class=\"kw-ttt\">lévofloxacine + métronidazole + gentamicine</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Relais per os</strong></td>\n            <td><span class=\"kw-ttt\">Amoxicilline - acide clavulanique</span> ;<br>OU <span class=\"kw-ttt\">fluoroquinolone + nitro-imidazolé</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <h5>Forme abcédée (Hinchey 1b-2)</h5>\n      <table >\n        <thead><tr><th>Taille de l'<span class=\"kw-clinique\">abcès</span></th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Petit <span class=\"kw-clinique\">abcès</span> &lt;<span class=\"kw-chiffre\"> 3-5 cm</span></strong></td>\n            <td><span class=\"kw-ttt\">ATB IV ≥ 7 jours</span> seule (faible risque de <span class=\"kw-alerte\">rupture</span>) ± <span class=\"kw-ttt\">drainage</span> si accessible en radiologie.</td>\n          </tr>\n          <tr>\n            <td><strong>Grand <span class=\"kw-clinique\">abcès</span> &gt;<span class=\"kw-chiffre\"> 3-5 cm</span></strong></td>\n            <td><span class=\"kw-alerte\">Drainage percutané sous scanner</span> + ATB adaptée aux prélèvements bactériologiques.</td>\n          </tr>\n          <tr>\n            <td><strong>Échec</strong></td>\n            <td><span class=\"kw-ttt\">Drainage</span> chirurgical par cœlioscopie ± résection-anastomose s<span class=\"kw-chiffre\">igm</span>oïdienne protégée par une <span class=\"kw-ttt\">iléostomie</span> d'amont.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":1},{"id":"287-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications d’une prise en charge chirurgicale d’une maladie diverticulaire et de ses complications","contenu":"<p><span class=\"kw-clinique\">Les</span> indications chirurgicales se répartissent en deux temps : la <strong><span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span></strong> et la <strong>résection élective à froid</strong>.</p>\n      <h5><span class=\"kw-ttt\">Chirurgie</span> en <span class=\"kw-alerte\">urgence</span></h5>\n      <table >\n        <thead><tr><th>Situation</th><th>Geste</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Péritonite généralisée</span> (Hinchey 3-4)</td>\n            <td><span class=\"kw-ttt\">Chirurgie</span> en <span class=\"kw-alerte\">urgence</span> après <strong>courte <span class=\"kw-alerte\">réanimation</span></strong> — la laparotomie reste la référence.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Chirurgie</span> en 1 temps</strong></td>\n            <td>Hinchey 3 opéré précocement : <span class=\"kw-ttt\">sigmoïdectomie</span> + anastomose colorectale protégée par une <span class=\"kw-ttt\">iléostomie</span> latérale temporaire.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Chirurgie</span> en 2 temps — intervention de Hartmann</strong></td>\n            <td><span class=\"kw-ttt\">Sigmoïdectomie</span> + fermeture du moignon rectal + <span class=\"kw-alerte\">colostomie d'amont</span> terminale ; rétablissement de continuité dans un 2<sup>e</sup> temps.<br>Indiquée si : <span class=\"kw-alerte\">instabilité hémodynamique</span>, <span class=\"kw-clinique\">péritonite</span> fécale (Hinchey 4), patient à haut risque (immunodépression, IR terminale, ASA &gt; 3).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Hémorragie diverticulaire réfractaire</span></td>\n            <td>La <span class=\"kw-ttt\">chirurgie</span> est une <strong>2<sup>nde</sup> intention</strong>, après échec ou impossibilité de l'<span class=\"kw-ttt\">hémostase endoscopique</span> (<span class=\"kw-ttt\">électrocoagulation</span>, clips, injection d'<span class=\"kw-ttt\">adrénaline</span>) et de l'<span class=\"kw-imagerie\">embolisation artérielle</span> :<br><span class=\"kw-ttt\">colectomie segmentaire</span> si le site <span class=\"kw-etio\">hémorragique</span> est localisé ; <span class=\"kw-ttt\">colectomie totale</span> si le site est inconnu avec diverticules diffus.</td>\n          </tr>\n        </tbody>\n      </table>\n      <h5>Résection élective à froid <em>(<span class=\"kw-chiffre\">≥ 2 mois</span> /<span class=\"kw-chiffre\"> 10 semaines</span> de la dernière <span class=\"kw-clinique\">poussée</span>)</em></h5>\n      <p><strong>Situations discutées</strong> — pas d'indication systématique ; le <span class=\"kw-chiffre\">nombre de poussées n'est PAS une indication</span> en soi :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Situation cible</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Diverticulite</span> compliquée</strong></td>\n            <td><span class=\"kw-alerte\">Abcès drainé</span>, <span class=\"kw-alerte\">fistule</span>, <span class=\"kw-alerte\">sténose symptomatique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span> à risque</strong></td>\n            <td>Patient <span class=\"kw-etio\">immunodéprimé</span> ou <span class=\"kw-etio\">insuffisant rénal chronique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes persistants</strong></td>\n            <td><span class=\"kw-clinique\">Douleurs / troubles du transit</span> après refroidissement d'une <span class=\"kw-clinique\">poussée</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Récidives fréquentes</strong></td>\n            <td>Impact significatif sur la qualité de vie (le seul nombre de poussées ne suffit pas).</td>\n          </tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Non indiquée :</strong> de façon systématique, ni après plusieurs poussées non compliquées, ni chez le sujet asymptomatique de moins de <span class=\"kw-chiffre\">50 ans</span>.</li>\n        <li><strong>Geste :</strong> <span class=\"kw-ttt\">sigmoïdectomie</span> emportant la jonction recto-s<span class=\"kw-chiffre\">igm</span>oïdienne (sans extension de la colectomie en amont, même en cas de diverticulose étendue) + <span class=\"kw-ttt\">anastomose colorectale haute</span> habituellement <strong>non protégée</strong> ; <span class=\"kw-ttt\">iléostomie de protection</span> recommandée si <span class=\"kw-clinique\">péritonite</span>, instabilité hémodynamique ou patient à haut risque + <span class=\"kw-imagerie\">analyse anatomopathologique systématique</span> de la pièce pour éliminer un cancer.</li>\n        <li><strong>Côlon droit :</strong> pas d'indication de <span class=\"kw-ttt\">chirurgie</span> à froid (le risque de récidive y est beaucoup plus faible).</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Piège — pneumopéritoine ≠ <span class=\"kw-ttt\">chirurgie</span> systématique.</strong> Une forme perforée (bulles de <span class=\"kw-imagerie\">pneumopéritoine</span> en <span class=\"kw-imagerie\">TDM</span>) <strong>sans signe clinique de <span class=\"kw-clinique\">péritonite</span></strong> peut relever d'un traitement <span class=\"kw-ttt\">médical seul</span> (repos digestif total + <span class=\"kw-ttt\">antibiothérapie</span>), sous <strong><span class=\"kw-def\">surveillance</span> clinique rapprochée</strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë · 355 — Hémorragie digestive</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Diverticulite</span> simple <span class=\"q\">(Hinchey 1a)</span></strong></p><p>PEC ambulatoire ou différée</p><ul><li>pas d'<span class=\"kw-alerte\">urgence</span></li></ul><p><strong><span class=\"kw-clinique\">Diverticulite</span> compliquée <span class=\"q\">(<span class=\"kw-clinique\">abcès</span> Hinchey 1b-2)</span></strong></p><p><span class=\"kw-alerte\">hospitalisation</span> systématique, <span class=\"kw-ttt\">ATB IV</span> sans délai ± <span class=\"kw-ttt\">drainage radiologique</span></p><p><strong><span class=\"kw-clinique\">Péritonite</span> <span class=\"q\">(Hinchey 3-4)</span></strong></p><p><span class=\"kw-ttt\">laparotomie</span> de référence</p><ul><li><span class=\"kw-alerte\">urgence chirurgicale</span> après <strong>courte <span class=\"kw-alerte\">réanimation</span></strong></li></ul><p><strong>Hémorragie diverticulaire</strong></p><ul><li><span class=\"kw-imagerie\">coloscopie totale &lt; 72h</span> (geste d'hémostase possible)</li><li>si <span class=\"kw-alerte\">retentissement HD sévère</span> → <span class=\"kw-alerte\">réanimation</span> + <span class=\"kw-imagerie\">EOGD</span> + <span class=\"kw-ttt\">hémostase endoscopique</span> en <span class=\"kw-alerte\">urgence</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-def\">diverticulite aiguë sigmoïdienne non compliquée</span> chez patient sans critère d'hospit (<span class=\"kw-ttt\">antalgiques</span> + <span class=\"kw-ttt\">régime sans résidu</span>, <span class=\"kw-ttt\">ATB PO</span> seulement si non-réponse à <span class=\"kw-chiffre\">48-72h</span>).<br><strong><span class=\"kw-alerte\">Hospitalisation</span> systématique si :</strong> <span class=\"kw-def\">forme compliquée</span> ; <span class=\"kw-etio\">grossesse</span> (quel que soit le terme) ; <span class=\"kw-alerte\">sepsis</span> (<span class=\"kw-chiffre\">qSOFA ≥ 2</span> : <span class=\"kw-chiffre\">PAS ≤ 100</span>, <span class=\"kw-chiffre\">FR ≥ 22</span>, <span class=\"kw-clinique\">confusion</span>) ; <span class=\"kw-def\">comorbidité</span> significative (<span class=\"kw-etio\">cancer évolutif</span>, <span class=\"kw-etio\">IR terminale</span>, <span class=\"kw-chiffre\">ASA &gt; 3</span>) ; <span class=\"kw-etio\">immunodépression</span> ; <span class=\"kw-ci\">intolérance</span> alimentaire imposant <span class=\"kw-ttt\">ATB IV</span> ; contexte social défavorable ; absence d'amélioration après <span class=\"kw-chiffre\">48-72h</span> d'ambu.<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-alerte\">instabilité hémodynamique</span>, <span class=\"kw-alerte\">choc septique</span> ou <span class=\"kw-alerte\">hémorragique</span>.<br><strong>Bloc opératoire en <span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-alerte\">péritonite généralisée</span> (Hinchey 3-4), <span class=\"kw-alerte\">hémorragie réfractaire</span> à l'<span class=\"kw-ttt\">endoscopie</span> + l'<span class=\"kw-ttt\">embolisation</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Péritonite</span> — <span class=\"kw-alerte\">contracture</span> (généralisée ou localisée en FIG), <span class=\"kw-alerte\">défense</span> des autres cadrans, <span class=\"kw-clinique\">douleur au TR</span></li><li><span class=\"kw-alerte\">Péritonite</span> — <span class=\"kw-alerte\">douleur à la décompression abdominale brutale</span> (<span class=\"kw-alerte\">irritation péritonéale</span>), <span class=\"kw-alerte\">syndrome occlusif</span> (<span class=\"kw-alerte\">iléus réflexe</span>)</li><li><span class=\"kw-alerte\">Sepsis sévère</span> — <span class=\"kw-chiffre\">qSOFA ≥ 2</span> (<span class=\"kw-alerte\">PAS ≤ 100 mmHg</span>, <span class=\"kw-alerte\">FR ≥ 22/min</span>, <span class=\"kw-alerte\">confusion</span>), <span class=\"kw-clinique\">fièvre élevée</span> + <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-alerte\">oligurie</span></li><li><span class=\"kw-alerte\">Choc</span> — surtout dans la <span class=\"kw-alerte\">péritonite stercorale</span> (charge <span class=\"kw-etio\">bactérienne</span> élevée)</li><li><span class=\"kw-alerte\">Hémorragie diverticulaire</span> — <span class=\"kw-clinique\">rectorragie/hématochézie</span> abondante de sang rouge avec caillots, <span class=\"kw-alerte\">instabilité hémodynamique</span> (PA, FC)</li><li>Biologie — <span class=\"kw-bio\">hyperPNN</span>, <span class=\"kw-bio\">CRP</span> <span class=\"kw-chiffre\">> 5 mg/L</span>, <span class=\"kw-bio\">insuffisance rénale fonctionnelle</span> (<span class=\"kw-bio\">créatinine</span>)</li><li><span class=\"kw-imagerie\">TDM</span> — <span class=\"kw-imagerie\">pneumopéritoine</span> (<span class=\"kw-imagerie\">bulles péri-coliques + inter-hépato-diaphragmatiques</span>), <span class=\"kw-imagerie\">épanchement liquidien</span> ± <span class=\"kw-imagerie\">granité fécal</span>, <span class=\"kw-imagerie\">extravasation de produit de contraste</span></li></ul>","principes":"<p>Adapter la PEC au tableau (<span class=\"kw-clinique\">diverticulite</span> <span class=\"kw-bio\">vs</span> hémorragie) ET à la <span class=\"kw-def\">classification</span> de Hinchey. ATB <strong>non systématique</strong> en non compliquée — réservée à la non-réponse au symptomatique. ATB IV si compliquée ou hospit. <span class=\"kw-ttt\">Chirurgie</span> d'<span class=\"kw-alerte\">urgence</span> réservée aux péritonites et à l'hémorragie réfractaire ; chirurgie à froid <strong>non systématique</strong> (le nombre de poussées n'est PAS une indication).</p><p><strong><span class=\"kw-clinique\">Diverticulite</span> simple ambulatoire</strong></p><ul><li><span class=\"kw-ttt\">antalgiques</span> + <span class=\"kw-ttt\">régime sans résidu</span> en phase aiguë</li><li>bilan <span class=\"kw-bio\">NFS</span>-<span class=\"kw-bio\">CRP</span>-<span class=\"kw-bio\">créatinine</span></li><li><span class=\"kw-ttt\">ATB PO</span> uniquement si non-réponse à <span class=\"kw-chiffre\">48-72h</span> (<span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> <span class=\"kw-chiffre\">≤ 7j</span> ; <span class=\"kw-ttt\">FQ</span> + <span class=\"kw-ttt\">métronidazole</span> si <span class=\"kw-ci\">allergie</span>)</li></ul><p><strong><span class=\"kw-clinique\">Diverticulite</span> compliquée <span class=\"q\">— ATB IV</span></strong></p><ul><li><span class=\"kw-ttt\">amox-clav</span> + <span class=\"kw-ttt\">gentamicine</span>, OU <span class=\"kw-ttt\">C3G</span> + <span class=\"kw-ttt\">métronidazole</span>, OU <span class=\"kw-ttt\">lévofloxacine</span> + <span class=\"kw-ttt\">métronidazole</span> + <span class=\"kw-ttt\">gentamicine</span> si <span class=\"kw-ci\">allergie</span> aux β-lactamines</li><li>relais PO par <span class=\"kw-ttt\">amox-clav</span> ou <span class=\"kw-ttt\">FQ</span> + <span class=\"kw-ttt\">nitro-imidazolé</span></li></ul><p><strong><span class=\"kw-clinique\">Abcès</span> &lt;<span class=\"kw-chiffre\"> 3-5 cm</span> <span class=\"q\">(faible risque de <span class=\"kw-alerte\">rupture</span>)</span></strong></p><ul><li><span class=\"kw-ttt\">ATB IV</span> <span class=\"kw-chiffre\">≥ 7j</span> seule ± <span class=\"kw-ttt\">drainage radiologique</span> si accessible</li></ul><p><strong><span class=\"kw-clinique\">Abcès</span> &gt;<span class=\"kw-chiffre\"> 3-5 cm</span></strong></p><ul><li><span class=\"kw-ttt\">drainage percutané sous scanner</span> + <span class=\"kw-ttt\">ATB</span> adaptée aux <span class=\"kw-bio\">prélèvements bactériologiques</span></li></ul><p><strong>Échec ATB + <span class=\"kw-ttt\">drainage</span></strong></p><ul><li><span class=\"kw-ttt\">drainage chirurgical par cœlioscopie</span> + <span class=\"kw-ttt\">résection-anastomose sigmoïdienne</span> ± <span class=\"kw-ttt\">iléostomie de protection</span></li></ul><p><strong><span class=\"kw-clinique\">Péritonite</span> Hinchey 3 <span class=\"q\">(purulente) opérée précocement</span></strong></p><ul><li><span class=\"kw-ttt\">sigmoïdectomie</span> + <span class=\"kw-ttt\">anastomose colorectale</span> protégée par <span class=\"kw-ttt\">iléostomie latérale temporaire</span> (1 temps)</li></ul><p><strong><span class=\"kw-clinique\">Péritonite</span> Hinchey 4 / instabilité HD / patient haut risque</strong></p><ul><li><span class=\"kw-ttt\">intervention de Hartmann</span> — <span class=\"kw-ttt\">sigmoïdectomie</span> + <span class=\"kw-ttt\">fermeture du moignon rectal</span> + <span class=\"kw-ttt\">colostomie d'amont terminale</span></li><li>rétablissement de continuité dans un 2ᵉ temps</li></ul><p><strong>Hémorragie diverticulaire <span class=\"q\">— 1ʳᵉ intention</span></strong></p><ul><li><span class=\"kw-ttt\">hémostase endoscopique</span> (<span class=\"kw-ttt\">électrocoagulation</span>, <span class=\"kw-ttt\">clips</span>, injection d'<span class=\"kw-ttt\">adrénaline</span>) OU <span class=\"kw-ttt\">embolisation radiologique</span> (<span class=\"kw-ttt\">coils</span>, <span class=\"kw-ttt\">colle biologique</span>)</li></ul><p><strong>Hémorragie réfractaire <span class=\"q\">— 2ᵉ intention chirurgicale</span></strong></p><ul><li><span class=\"kw-ttt\">colectomie segmentaire</span> si site localisé en préop, <span class=\"kw-ttt\">colectomie totale</span> à l'aveugle si site inconnu + diverticules diffus</li></ul><p><strong>Forme perforée <span class=\"q\">(pneumopéritoine <span class=\"kw-imagerie\">TDM</span>) SANS signe de <span class=\"kw-clinique\">péritonite</span></span></strong></p><ul><li>traitement médical seul possible (<span class=\"kw-ttt\">repos digestif total</span> + <span class=\"kw-ttt\">ATB</span>) sous <span class=\"kw-def\">surveillance</span> clinique rapprochée</li></ul>","suivi":"<p><strong>Après 1ʳᵉ <span class=\"kw-clinique\">poussée</span> non compliquée :</strong> <span class=\"kw-def\">surveillance</span> clinique simple ; <span class=\"kw-ttt\">corticoïdes</span> et <span class=\"kw-ttt\">AINS</span> déconseillés au long cours (aggravent le risque de <span class=\"kw-alerte\">récidive compliquée</span>).<br><strong>Après poussée compliquée :</strong> <span class=\"kw-imagerie\">coloscopie à ≈ 6 semaines</span> (post-refroidissement) — éliminer un <span class=\"kw-def\">cancer associé</span> et dépister.<br><strong>Résection élective à froid (s<span class=\"kw-chiffre\">igm</span>oïdectomie) :</strong> à <span class=\"kw-chiffre\">≥ 2 mois / 10 semaines</span> de la dernière poussée — <strong>discutée</strong> (jamais systématique) si : <span class=\"kw-def\">abcès drainé</span>, <span class=\"kw-def\">fistule</span>, <span class=\"kw-def\">sténose symptomatique</span>, <span class=\"kw-etio\">immunodépression</span>, <span class=\"kw-etio\">IRC</span>, symptômes persistants, récidives impactant la qualité de vie.<br><strong>Non indiquée :</strong> après plusieurs poussées non compliquées, ni chez le sujet asymptomatique <span class=\"kw-chiffre\">&lt; 50 ans</span>, ni sur le côlon droit.<br><strong>Geste opératoire :</strong> <span class=\"kw-ttt\">sigmoïdectomie</span> emportant la jonction recto-sigmoïdienne (sans extension amont, même si diverticulose étendue) + <span class=\"kw-ttt\">anastomose colorectale haute</span> habituellement non protégée + <strong>analyse <span class=\"kw-bio\">anatomopathologique</span> systématique</strong> de la pièce.<br><strong>Aucune mesure préventive</strong> (régime, antiseptiques intestinaux) n'a démontré son efficacité.</p>"},"liensGlobaux":[{"href":"https://www.abcd-chirurgie.fr/les-interventions/colon/intervention-de-hartmann","label":"Intervention de hartmann"},{"href":"http://www.isurgery.ch/Isurgery/Blog_Isurgery/Entrees/2015/4/18_Les_Stenoses_Sigmoidiennes_Diverticulaires_une_forme_de_la_maladie_diverticulaire_1.html","label":"18 les stenoses sigmoidiennes diverticulaires une forme de la maladie diverticulaire 1"},{"href":"https://www.vidal.fr/maladies/estomac-intestins/diverticulose-diverticulite.html","label":"Diverticulose diverticulite"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Maladie diverticulaire symptomatique — Premier tri clinique","detail":"<h4>CAT — maladie diverticulaire symptomatique — <span class=\"kw-clinique\">Diverticulite</span> aiguë (Hinchey) + hémorragie diverticulaire</h4>","branches":[{"to":"q-tdm-hinchey","label":"Tableau de diverticulite aiguë","color":"amber"},{"to":"q-tolerance-hd","label":"Hémorragie diverticulaire","color":"red"}]},{"id":"q-tdm-hinchey","kind":"decision","label":"TDM-AP injectée systématique — classification de Hinchey — Douleur FIG + fièvre + sd inflammatoire","branches":[{"to":"q-criteres-hospit","label":"Hinchey 1a · non compliquée","color":"green"},{"to":"q-taille-abces","label":"Hinchey 1b-2 · abcès","color":"amber"},{"to":"t-hinchey3","label":"Hinchey 3 · péritonite purulente","color":"red"},{"to":"t-hartmann","label":"Hinchey 4 · stercorale OU instabilité HD","color":"red"}]},{"id":"q-criteres-hospit","kind":"decision","label":"Critères d'hospitalisation ? — Grossesse · qSOFA ≥ 2 · ASA > 3 · immunodep · comorbidité · social · échec ambu 48-72h","branches":[{"to":"t-ambu","label":"Non — aucun critère","color":"green"},{"to":"t-hospit-iv","label":"Oui — au moins 1 critère","color":"amber"}]},{"id":"t-ambu","kind":"terminal","label":"Ambulatoire","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antalgiques</span></li><li><span class=\"kw-ttt\">Régime sans résidu</span> pendant la phase aiguë</li><li><span class=\"kw-ttt\">ATB PO</span> non systématique — uniquement si non-réponse à <span class=\"kw-chiffre\">48-72h</span> : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> <span class=\"kw-chiffre\">≤ 7 jours</span> (<span class=\"kw-ttt\">FQ</span> + <span class=\"kw-ttt\">métronidazole</span> si <span class=\"kw-ci\">allergie</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> clinique à <span class=\"kw-chiffre\">48-72h</span> ; <span class=\"kw-alerte\">hospitalisation</span> si absence d'amélioration.</li></ul><h4>À distance</h4><ul><li><span class=\"kw-def\">Surveillance</span> clinique simple (1ʳᵉ <span class=\"kw-clinique\">poussée</span> non compliquée). Éviter <span class=\"kw-ttt\">corticoïdes</span> et <span class=\"kw-ttt\">AINS</span> au long cours.</li></ul>"},{"id":"t-hospit-iv","kind":"terminal","label":"Hospitalisation + ATB IV","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-etio\">Grossesse</span> (quel que soit le terme)</li><li><span class=\"kw-chiffre\">qSOFA ≥ 2</span> (<span class=\"kw-chiffre\">PAS ≤ 100</span>, <span class=\"kw-chiffre\">FR ≥ 22</span>, <span class=\"kw-clinique\">confusion</span>)</li><li><span class=\"kw-def\">Comorbidité</span> significative ou <span class=\"kw-chiffre\">ASA > 3</span></li><li><span class=\"kw-etio\">Immunodépression</span> (<span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">immunosuppresseurs</span>)</li><li><span class=\"kw-ci\">Intolérance</span> alimentaire</li><li>Contexte social défavorable / échec ambu <span class=\"kw-chiffre\">48-72h</span></li></ul><h4><span class=\"kw-ttt\">Antibiothérapie</span> IV</h4><ul><li><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span> + <span class=\"kw-ttt\">gentamicine</span></li><li>OU <span class=\"kw-ttt\">C3G</span> + <span class=\"kw-ttt\">métronidazole</span></li><li>Si <span class=\"kw-ci\">allergie</span> β-lactamines : <span class=\"kw-ttt\">lévofloxacine</span> + <span class=\"kw-ttt\">métronidazole</span> + <span class=\"kw-ttt\">gentamicine</span></li><li>Relais PO : <span class=\"kw-ttt\">amox-clav</span> OU <span class=\"kw-ttt\">FQ</span> + <span class=\"kw-ttt\">nitro-imidazolé</span></li></ul>"},{"id":"q-taille-abces","kind":"decision","label":"Taille de l'abcès ? — Seuil 3-5 cm","branches":[{"to":"t-abces-petit","label":"< 3-5 cm","color":"amber"},{"to":"t-abces-grand","label":"> 3-5 cm","color":"amber"}]},{"id":"t-abces-petit","kind":"terminal","label":"Hospit + ATB IV ≥ 7 jours ± drainage","color":"amber","detail":"<h4>Rationnel</h4><ul><li>Petits <span class=\"kw-clinique\">abcès</span> = faible risque de <span class=\"kw-alerte\">rupture secondaire</span> et de <span class=\"kw-alerte\">péritonite généralisée</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">ATB probabiliste IV</span> <span class=\"kw-chiffre\">≥ 7 jours</span> (durée selon <span class=\"kw-clinique\">évolution</span> clinique) = traitement de référence</li><li><span class=\"kw-ttt\">Drainage radiologique</span> si <span class=\"kw-clinique\">abcès</span> accessible (recommandation récente)</li><li>Si échec <span class=\"kw-ttt\">ATB</span> ± <span class=\"kw-ttt\">drainage</span> : <span class=\"kw-ttt\">drainage chirurgical par cœlioscopie</span> + <span class=\"kw-ttt\">résection-anastomose</span> ± <span class=\"kw-ttt\">iléostomie</span></li></ul>"},{"id":"t-abces-grand","kind":"terminal","label":"Drainage percutané sous scanner + ATB","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-def\">Péritonite diverticulaire localisée</span> avec <span class=\"kw-clinique\">abcès</span> de grande taille, surtout chez patient <span class=\"kw-chiffre\">ASA ≥ 3</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Drainage percutané radiologique</span> (sous <span class=\"kw-imagerie\">scanner</span>)</li><li><span class=\"kw-ttt\">ATB IV</span> adaptée aux <span class=\"kw-bio\">prélèvements bactériologiques</span> réalisés lors du <span class=\"kw-ttt\">drainage</span></li><li>Si échec : <span class=\"kw-ttt\">drainage chirurgical par cœlioscopie</span> + <span class=\"kw-ttt\">résection-anastomose sigmoïdienne</span> ± <span class=\"kw-ttt\">iléostomie d'amont</span></li></ul><h4>Piège</h4><ul><li><span class=\"kw-ttt\">Lavage péritonéal simple par cœlioscopie</span> n'est PLUS recommandé en cas d'échec (<span class=\"kw-alerte\">complications infectieuses</span> fréquentes).</li></ul>"},{"id":"t-hinchey3","kind":"terminal","label":"Urgence chir — Sigmoïdectomie + anastomose protégée","color":"red","detail":"<h4>Délai</h4><ul><li><span class=\"kw-ttt\">Intervention chirurgicale</span> en <span class=\"kw-alerte\">urgence</span>, précédée d'une courte <span class=\"kw-alerte\">réanimation</span>.</li></ul><h4>Voie d'abord</h4><ul><li>Pas de recommandation formelle, mais la <span class=\"kw-ttt\">laparotomie</span> reste la référence.</li></ul><h4>Geste — 1 temps (opération précoce)</h4><ul><li><span class=\"kw-ttt\">Sigmoïdectomie</span> (résection du segment pathologique emportant la jonction recto-s<span class=\"kw-chiffre\">igm</span>oïdienne)</li><li><span class=\"kw-ttt\">Anastomose colorectale</span> TOUJOURS protégée par une <span class=\"kw-ttt\">iléostomie latérale temporaire</span></li><li>Objectif : réduire le risque de <span class=\"kw-alerte\">désunion anastomotique</span></li></ul>"},{"id":"t-hartmann","kind":"terminal","label":"Urgence chir — Intervention de Hartmann (2 temps)","color":"red","detail":"<h4>Indication</h4><ul><li><span class=\"kw-alerte\">Péritonite stercorale</span> (Hinchey 4) — pour beaucoup d'équipes en pratique</li><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> (<span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-alerte\">sepsis sévère</span>)</li><li>Patient à haut risque : <span class=\"kw-etio\">immunodépression</span>, <span class=\"kw-etio\">corticothérapie chronique</span>, <span class=\"kw-etio\">cancer évolutif</span>, <span class=\"kw-etio\">IR terminale</span>, <span class=\"kw-chiffre\">ASA > 3</span></li></ul><h4>Geste — 1ᵉʳ temps</h4><ul><li><span class=\"kw-ttt\">Sigmoïdectomie</span></li><li><span class=\"kw-ttt\">Fermeture/suture du moignon rectal</span></li><li><span class=\"kw-ttt\">Colostomie d'amont terminale en FIG</span></li></ul><h4>Geste — 2ᵉ temps</h4><ul><li><span class=\"kw-ttt\">Rétablissement secondaire de la continuité digestive</span>, à distance.</li></ul><h4>Piège</h4><ul><li><span class=\"kw-alerte\">Forme perforée</span> (<span class=\"kw-imagerie\">pneumopéritoine</span> <span class=\"kw-imagerie\">TDM</span>) SANS signe clinique de <span class=\"kw-alerte\">péritonite</span> → traitement médical seul possible (<span class=\"kw-ttt\">repos digestif total</span> + <span class=\"kw-ttt\">ATB</span>) sous <span class=\"kw-def\">surveillance</span> rapprochée.</li></ul>"},{"id":"q-tolerance-hd","kind":"decision","label":"Retentissement hémodynamique sévère ? — Rectorragie/hématochézie sang rouge brutale + caillots — indépendante d'une poussée","branches":[{"to":"t-colo-72h","label":"Non — patient tolérant","color":"amber"},{"to":"t-rea-hd","label":"Oui — choc / instabilité","color":"red"}]},{"id":"t-colo-72h","kind":"terminal","label":"<span class=\"kw-imagerie\">Coloscopie</span> totale <span class=\"kw-chiffre\">< 72</span>h après préparation","color":"amber","detail":"<h4>Stratégie diagnostique</h4><ul><li><span class=\"kw-imagerie\">EOGD</span> pour éliminer une cause haute (si <span class=\"kw-alerte\">hémorragie abondante</span> mal tolérée)</li><li><span class=\"kw-imagerie\">Anuscopie</span> / <span class=\"kw-imagerie\">rectosigmoïdoscopie</span> pour éliminer une cause basse de saignement</li><li><span class=\"kw-imagerie\">Coloscopie totale</span> après préparation rapide au <span class=\"kw-ttt\">polyéthylène glycol (PEG)</span> — dans <span class=\"kw-clinique\">les</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">72h</span></span></li></ul><h4>Traitement — 1ʳᵉ intention</h4><ul><li><span class=\"kw-ttt\">Hémostase endoscopique</span> : <span class=\"kw-ttt\">électrocoagulation</span>, <span class=\"kw-ttt\">clips</span>, injection d'<span class=\"kw-ttt\">adrénaline</span></li><li>OU <span class=\"kw-ttt\">embolisation radiologique</span> : <span class=\"kw-ttt\">coils</span>, <span class=\"kw-ttt\">colle biologique intra-artérielle</span></li></ul><h4><span class=\"kw-clinique\">Évolution</span></h4><ul><li>Résolution spontanée sous traitement conservateur dans <span class=\"kw-chiffre\">80-85 %</span> des cas. Récidive ≈ <span class=\"kw-chiffre\">15 %</span> après 1ᵉʳ épisode, <span class=\"kw-chiffre\">50 %</span> après le 2ᵉ.</li></ul><h4>Examens 2ᵉ ligne (rares)</h4><ul><li><span class=\"kw-imagerie\">TDM-AP injectée</span> et <span class=\"kw-imagerie\">artériographie mésentérique</span> — confirment l'origine et guident le traitement si <span class=\"kw-imagerie\">endoscopie</span> ne localise pas le saignement.</li></ul>"},{"id":"t-rea-hd","kind":"terminal","label":"Réa + EOGD + hémostase en urgence","color":"red","detail":"<h4><span class=\"kw-alerte\">Réanimation</span></h4><ul><li><span class=\"kw-ttt\">Remplissage</span>, <span class=\"kw-ttt\">transfusion</span> si besoin</li><li>Monitorage hémodynamique (<span class=\"kw-clinique\">PA</span>, <span class=\"kw-clinique\">FC</span>, <span class=\"kw-clinique\">diurèse</span>)</li><li>Bilan <span class=\"kw-ttt\">biologique</span> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">groupage</span></li></ul><h4>Stratégie endoscopique</h4><ul><li><span class=\"kw-imagerie\">EOGD</span> en <span class=\"kw-alerte\">urgence</span> pour éliminer une cause haute</li><li><span class=\"kw-ttt\">Hémostase endoscopique colique</span> (<span class=\"kw-ttt\">clips</span>, <span class=\"kw-ttt\">électrocoagulation</span>, <span class=\"kw-ttt\">adrénaline</span>)</li></ul><h4>Si échec endoscopique</h4><ul><li><span class=\"kw-ttt\">Embolisation radiologique</span> en 2ᵉ intention</li><li><span class=\"kw-ttt\">Chirurgie</span> en 3ᵉ intention : <span class=\"kw-ttt\">colectomie segmentaire</span> si site localisé, <span class=\"kw-ttt\">colectomie totale</span> à l'aveugle si site inconnu + diverticules diffus</li></ul>"}]},"cards":[{"i":"0ceebd0f7db2","n":287,"o":"287-1","u":"Définition","t":"Connaître la définition d’un diverticule, de la diverticulose, de la diverticulite, de la diverticulite compliquée (abcès, péritonite, fistule, hémorragie, sténose)","q":"Quelle est la définition d'un diverticule colique ?","a":"<p>Un diverticule colique est une <strong>hernie acquise</strong> de la <strong>muqueuse et de la sous-muqueuse</strong> à travers une zone de faiblesse de la paroi musculaire du côlon, au point de pénétration des vaisseaux coliques. Il s'agit d'un <strong>pseudo-diverticule</strong> car il ne contient pas toute la paroi colique.</p>"},{"i":"84283888325d","n":287,"o":"287-1","u":"Définition","t":"Connaître la définition d’un diverticule, de la diverticulose, de la diverticulite, de la diverticulite compliquée (abcès, péritonite, fistule, hémorragie, sténose)","q":"Quelles sont les complications définissant une diverticulite compliquée ?","a":"<p>Les complications locales définissant une diverticulite compliquée sont :</p><ul><li>Un <strong>abcès</strong></li><li>Une <strong>fistule</strong></li><li>Une <strong>péritonite</strong> d'origine diverticulaire</li><li>Une <strong>sténose</strong></li></ul>"},{"i":"899ea05d378b","n":287,"o":"287-1","u":"Définition","t":"Connaître la définition d’un diverticule, de la diverticulose, de la diverticulite, de la diverticulite compliquée (abcès, péritonite, fistule, hémorragie, sténose)","q":"Comment définit-on la diverticulose colique ?","a":"<p>La diverticulose colique est la <strong>présence de diverticules acquis du côlon</strong>. Elle est, par définition, un état <strong>asymptomatique</strong>.</p>"},{"i":"e2412e30335e","n":287,"o":"287-1","u":"Définition","t":"Connaître la définition d’un diverticule, de la diverticulose, de la diverticulite, de la diverticulite compliquée (abcès, péritonite, fistule, hémorragie, sténose)","q":"Qu'est-ce que la diverticulite ?","a":"<p>La diverticulite est une <strong>inflammation ou une infection</strong> d'origine diverticulaire. La <strong>sigmoïdite diverticulaire</strong> est sa forme habituelle, touchant le côlon sigmoïde.</p>"},{"i":"1c43408d3754","n":287,"o":"287-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge médicale d’une diverticulite aiguë non compliquée","q":"Quelles sont les indications justifiant une hospitalisation pour une diverticulite aiguë ?","a":"<p>Les indications d'hospitalisation pour une diverticulite aiguë sont :</p><ul><li>Une <strong>forme compliquée</strong>.</li><li>Une <strong>intolérance alimentaire</strong> nécessitant une antibiothérapie par voie IV.</li><li>Un <strong>contexte social défavorable</strong> (surveillance ambulatoire impossible).</li><li>Une <strong>comorbidité significative</strong>.</li><li>L'<strong>absence d'amélioration</strong> après 48-72 heures de traitement ambulatoire.</li></ul>"},{"i":"58a30bc30301","n":287,"o":"287-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge médicale d’une diverticulite aiguë non compliquée","q":"Quelles sont les recommandations à distance d'un premier épisode de diverticulite aiguë non compliquée concernant la surveillance, les médicaments et la chirurgie ?","a":"<p>À distance d'un premier épisode non compliqué de diverticulite aiguë :</p><ul><li>La surveillance est <strong>clinique simple</strong>.</li><li>Les <strong>corticoïdes et AINS sont déconseillés</strong> en cas d'antécédents de diverticulite.</li><li>La <strong>chirurgie n'est pas systématique</strong>, le nombre de poussées n'étant pas une indication opératoire en soi.</li></ul>"},{"i":"daa2f8b629c1","n":287,"o":"287-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge médicale d’une diverticulite aiguë non compliquée","q":"Quelle est la stratégie initiale de prise en charge ambulatoire d'une diverticulite aiguë sigmoïdienne non compliquée ?","a":"<p>La diverticulite aiguë sigmoïdienne non compliquée est majoritairement traitée en ambulatoire. La prise en charge repose sur :</p><ul><li>Des <strong>antalgiques</strong>.</li><li>Un <strong>régime alimentaire</strong> : <strong>sans résidu</strong> en phase aiguë, puis une alimentation non restrictive est recommandée au long cours.</li><li>Un bilan biologique avec <strong>NFS, CRP, créatinine</strong>.</li><li>L'<strong>antibiothérapie n'est plus systématique</strong>.</li></ul>"},{"i":"e9201d762830","n":287,"o":"287-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge médicale d’une diverticulite aiguë non compliquée","q":"Dans quels cas une antibiothérapie est-elle indiquée pour une diverticulite aiguë non compliquée et quelles sont les modalités ?","a":"<p>L'antibiothérapie pour une diverticulite aiguë non compliquée n'est pas systématique et est réservée à la <strong>non-réponse au traitement symptomatique</strong>. Les modalités sont :</p><ul><li><strong>Molécule</strong> : <strong>Amoxicilline - acide clavulanique</strong> (ou fluoroquinolone + métronidazole en cas d'allergie).</li><li><strong>Durée</strong> : <strong>≤ 7 jours</strong>.</li><li><strong>Voie</strong> : per os.</li></ul>"},{"i":"00a4ec51bc5b","n":287,"o":"287-12","u":"Prise en charge","t":"Connaître les indications d’une prise en charge chirurgicale d’une maladie diverticulaire et de ses complications","q":"Quel est le geste chirurgical réalisé lors d'une résection élective à froid pour une diverticulose colique ?","a":"<p>Le geste chirurgical est une <strong>sigmoïdectomie emportant la jonction recto-sigmoïdienne</strong> avec <strong>anastomose colorectale haute</strong>. Une <strong>iléostomie de protection</strong> est recommandée en cas de péritonite, instabilité hémodynamique ou patient à haut risque. Une <strong>analyse anatomopathologique systématique</strong> de la pièce est réalisée pour éliminer un cancer.</p>"},{"i":"5900305b7944","n":287,"o":"287-12","u":"Prise en charge","t":"Connaître les indications d’une prise en charge chirurgicale d’une maladie diverticulaire et de ses complications","q":"Dans quelles situations réalise-t-on une intervention de Hartmann en urgence pour une diverticulite colique ?","a":"<p>L'<strong>intervention de Hartmann</strong> (sigmoïdectomie, fermeture du moignon rectal et colostomie d'amont terminale, avec rétablissement de continuité dans un 2<sup>e</sup> temps) est indiquée en urgence en cas de :</p><ul><li><strong>Instabilité hémodynamique</strong>.</li><li><strong>Péritonite fécale</strong> (Hinchey 4).</li><li>Patient à <strong>haut risque</strong> (immunodépression, insuffisance rénale terminale, ASA &gt; 3).</li></ul>"},{"i":"8866e008b19f","n":287,"o":"287-12","u":"Prise en charge","t":"Connaître les indications d’une prise en charge chirurgicale d’une maladie diverticulaire et de ses complications","q":"Quel geste chirurgical est réalisé en urgence en cas de péritonite généralisée Hinchey 3 dans la diverticulite colique ?","a":"<p>En cas de péritonite généralisée Hinchey 3 opérée précocement, le geste chirurgical de référence est une <strong>sigmoïdectomie</strong> avec <strong>anastomose colorectale protégée par une iléostomie latérale temporaire</strong> (chirurgie en 1 temps).</p>"},{"i":"bb4c452c01c7","n":287,"o":"287-12","u":"Prise en charge","t":"Connaître les indications d’une prise en charge chirurgicale d’une maladie diverticulaire et de ses complications","q":"Quelles sont les indications de chirurgie en urgence dans la diverticulite colique et ses complications ?","a":"<p>Les indications de chirurgie en urgence pour la diverticulite colique incluent :</p><ul><li>La <strong>péritonite généralisée</strong> (Hinchey 3-4).</li><li>L'<strong>hémorragie diverticulaire réfractaire</strong>, après échec ou impossibilité de l'hémostase endoscopique et de l'embolisation artérielle.</li></ul>"},{"i":"cdc2c78ddd5b","n":287,"o":"287-12","u":"Prise en charge","t":"Connaître les indications d’une prise en charge chirurgicale d’une maladie diverticulaire et de ses complications","q":"Le pneumopéritoine visible au scanner impose-t-il systématiquement une chirurgie dans le contexte d'une diverticulite ?","a":"<p>Non, la présence de pneumopéritoine (bulles de gaz en TDM) dans le cadre d'une diverticulite ne nécessite <strong>pas systématiquement une chirurgie</strong>. Si la perforation est de petite taille <strong>sans signes cliniques de péritonite</strong>, un traitement médical seul (repos digestif total et antibiothérapie) sous surveillance rapprochée peut être suffisant.</p>"},{"i":"faf2e4822520","n":287,"o":"287-12","u":"Prise en charge","t":"Connaître les indications d’une prise en charge chirurgicale d’une maladie diverticulaire et de ses complications","q":"Quelles sont les indications d'une résection élective à froid (chirurgie programmée) pour une diverticulose colique ?","a":"<p>Les indications de résection élective à froid (réalisée au moins 2 mois/10 semaines après la dernière poussée) sont discutées et incluent :</p><ul><li>La <strong>diverticulite compliquée</strong> (abcès drainé, fistule, sténose symptomatique).</li><li>Un <strong>terrain à risque</strong> (patient immunodéprimé ou insuffisant rénal chronique).</li><li>Des <strong>symptômes persistants</strong> (douleurs, troubles du transit) après refroidissement d'une poussée.</li><li>Des <strong>récidives fréquentes</strong> avec un impact significatif sur la qualité de vie (le simple nombre de poussées n'est pas une indication en soi).</li></ul>"},{"i":"0f811b35ef73","n":287,"o":"287-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un diverticule, d’une diverticulose, d’une diverticulite, d’une diverticulite compliquée","q":"Quels sont les signes cliniques suggestifs d'une diverticulite aiguë et quel est l'examen diagnostique clé ?","a":"<p>Cliniquement, une diverticulite se manifeste par :</p><ul><li>Une <strong>douleur de la fosse iliaque gauche</strong> ou de l'hypogastre.</li><li>Une <strong>fièvre modérée</strong>.</li><li>Des <strong>troubles du transit</strong>, principalement une <strong>constipation</strong>.</li><li>Des signes fonctionnels urinaires.</ul><p>Le diagnostic de certitude est posé par un <strong>TDM-AP injecté en urgence</strong>, qui montre un <strong>épaississement pariétal > 4 mm</strong>, une <strong>infiltration de la graisse péricolique</strong> et le <strong>signe du peigne</strong>. La présence de diverticules n'est pas indispensable pour le diagnostic TDM de diverticulite.</p>"},{"i":"23fbe30b47b4","n":287,"o":"287-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un diverticule, d’une diverticulose, d’une diverticulite, d’une diverticulite compliquée","q":"Comment diagnostique-t-on un diverticule ou une diverticulose colique ?","a":"<p>Un diverticule ou une diverticulose est généralement une découverte <strong>fortuite</strong> lors d'une <strong>coloscopie</strong> ou d'un <strong>TDM-TAP</strong>, révélant de multiples images d'addition aérique du cadre colique.</p>"},{"i":"2bd1669d6918","n":287,"o":"287-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un diverticule, d’une diverticulose, d’une diverticulite, d’une diverticulite compliquée","q":"Quels sont les signes radiologiques d'une diverticulite compliquée au TDM et les signes cliniques associés aux fistules ?","a":"<p>La TDM recherche les complications suivantes :</p><ul><li><strong>Abcès</strong> : collection hypodense, paroi rehaussée, niveau hydro-aérique.</li><li><strong>Péritonite</strong> : <strong>pneumopéritoine</strong>, épanchement liquidien ± granité fécal.</li><li><strong>Fistule colo-vésicale</strong> :</li><ul><li>Signe TDM : <strong>pneumovessie</strong>.</li><li>Signes cliniques : <strong>pneumaturie</strong>, <strong>fécalurie</strong> (signe pathognomonique), infections urinaires polymicrobiennes (germes digestifs).</li></ul><li><strong>Fistule colo-vaginale</strong> :</li><ul><li>Signes cliniques : émission de gaz/matières par voie vaginale, infections vaginales récidivantes. Concerne la femme hystérectomisée.</li></ul><li><strong>Sténose</strong> : inflammatoire (régresse sous antibiothérapie) ou fibreuse pseudo-tumorale (cicatricielle, ne régresse pas, relève de la chirurgie).</ul>"},{"i":"f7440614935e","n":287,"o":"287-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un diverticule, d’une diverticulose, d’une diverticulite, d’une diverticulite compliquée","q":"Quelles sont les contre-indications majeures aux examens complémentaires durant la phase aiguë d'une diverticulite ?","a":"<p>En phase aiguë de diverticulite, la <strong>coloscopie conventionnelle</strong>, la <strong>coloscopie virtuelle</strong> et le <strong>lavement baryté sont contre-indiqués</strong> en raison du <strong>risque de perforation</strong>. La coloscopie n'est réalisée qu'à distance, après résolution de l'épisode aigu.</p>"},{"i":"47cd02380a46","n":287,"o":"287-6","u":"Identifier une urgence","t":"Identifier les signes de gravité des deux urgences compliquant une maladie diverticulaire : une péritonite perforée et une hémorragie diverticulaire","q":"Quels sont les signes d'une hémorragie diverticulaire compliquant une maladie diverticulaire et comment en évaluer la gravité ?","a":"<p>Les signes d'une hémorragie diverticulaire sont ceux d'une <strong>hémorragie digestive basse brutale</strong> :</p><ul><li><strong>Rectorragie ou hématochézie abondante</strong> de sang rouge avec caillots.</li><li>Plus rarement, <strong>méléna</strong> si le diverticule hémorragique est en amont de l'angle colique gauche.</li></ul><p>L'évaluation de la gravité repose sur le <strong>retentissement hémodynamique</strong> :</p><ul><li>Mesure de la <strong>pression artérielle</strong>.</li><li>Mesure de la <strong>fréquence cardiaque</strong>.</li><li>Recherche de <strong>signes de choc hémorragique</strong>.</li></ul><p>Une hémorragie diverticulaire survient <strong>indépendamment d'une poussée de diverticulite</strong>, et il n'y a pas de rectorragie dans la diverticulite simple.</p>"},{"i":"603cb333a67d","n":287,"o":"287-6","u":"Identifier une urgence","t":"Identifier les signes de gravité des deux urgences compliquant une maladie diverticulaire : une péritonite perforée et une hémorragie diverticulaire","q":"Comment différencier une péritonite purulente d'une péritonite stercorale compliquant une maladie diverticulaire ?","a":"<p>La péritonite purulente est une perforation en deux temps, souvent suite à la rupture d'un abcès péri-sigmoïdien. La péritonite stercorale est une perforation diverticulaire d'emblée en péritoine libre.</p><p>Sur le plan clinique, les <strong>signes de choc</strong> dominent plus particulièrement dans la péritonite stercorale, du fait d'une charge bactérienne plus élevée.</p>"},{"i":"d7683bca3b1f","n":287,"o":"287-6","u":"Identifier une urgence","t":"Identifier les signes de gravité des deux urgences compliquant une maladie diverticulaire : une péritonite perforée et une hémorragie diverticulaire","q":"Quel examen d'imagerie est essentiel pour confirmer le diagnostic de péritonite perforée et rechercher des signes de gravité ?","a":"<p>La <strong>TDM abdominale</strong> (Tomodensitométrie) est l'examen essentiel. Elle peut objectiver un <strong>pneumopéritoine</strong>, signe de perforation digestive.</p>"},{"i":"eaff94f86a28","n":287,"o":"287-6","u":"Identifier une urgence","t":"Identifier les signes de gravité des deux urgences compliquant une maladie diverticulaire : une péritonite perforée et une hémorragie diverticulaire","q":"Quels sont les circonstances ou les signes cliniques qui doivent faire suspecter une péritonite perforée chez un patient présentant une maladie diverticulaire ?","a":"<p>Une péritonite perforée doit être suspectée devant :</p><ul><li>Des <strong>signes péritonéaux</strong> : contracture (généralisée ou localisée à la Fosse Iliaque Gauche - FIG), défense, douleur au toucher rectal.</li><li>Un <strong>syndrome occlusif</strong> lié à un iléus réflexe.</li><li>Un <strong>syndrome infectieux</strong> avec fièvre élevée.</li><li>Des <strong>signes de choc</strong>, particulièrement en cas de péritonite stercorale.</li><li>Des <strong>drapeaux d'abcès</strong> : défense en FIG, douleur à la décompression abdominale brutale.</li></ul>"},{"i":"f19b964a58ec","n":287,"o":"287-6","u":"Identifier une urgence","t":"Identifier les signes de gravité des deux urgences compliquant une maladie diverticulaire : une péritonite perforée et une hémorragie diverticulaire","q":"Quelles sont les caractéristiques cliniques et biologiques d'une péritonite perforée compliquant une maladie diverticulaire ?","a":"<p>Les caractéristiques cliniques incluent :</p><ul><li><strong>Signes péritonéaux</strong> : contracture, défense, douleur au toucher rectal.</li><li><strong>Syndrome occlusif</strong> (iléus réflexe).</li><li><strong>Syndrome infectieux</strong> (fièvre élevée).</li><li><strong>Signes de choc</strong> (prédominant dans la péritonite stercorale).</li></ul><p>Sur le plan biologique, on peut observer :</p><ul><li><strong>Hyperleucocytose à polynucléaires neutrophiles (hyperPNN)</strong>.</li><li><strong>CRP > 5 mg/L</strong>.</li><li>Elévation de la <strong>créatinine</strong> en cas d'insuffisance rénale fonctionnelle si choc.</p></li></ul>"}]};